    <div>
      <div class="brand">PATCHPAD <span>Incident workspace</span></div>
      <h1 id="document-title">Loading document…</h1>
      <p id="document-meta"></p>
    </div>
    <div class="header-actions">
      <span id="save-state" class="state-pill">Loading</span>
      <button id="history-button" type="button">Revision history</button>
      <button id="save-button" class="primary" type="button">Save</button>
    </div>
  </header>

  <main>
    <section class="toolbar" aria-label="Editor controls">
      <div class="button-group">
        <button id="undo-button" type="button" title="Undo (Ctrl/Cmd+Z)">↶ Undo</button>
        <button id="redo-button" type="button" title="Redo (Ctrl/Cmd+Y)">↷ Redo</button>
      </div>
      <div class="search-group" role="search">
        <label>Find <input id="find-input" type="search" autocomplete="off"></label>
        <label>Replace <input id="replace-input" type="text" autocomplete="off"></label>
        <button id="find-button" type="button">Find Next</button>
        <button id="replace-button" type="button">Replace Current</button>
        <button id="replace-all-button" type="button">Replace All</button>
        <span id="match-status" aria-live="polite"></span>
      </div>
    </section>

    <div id="message" class="message" role="alert" hidden></div>
    <section class="editor-shell" aria-label="Document editor">
      <div id="editor" tabindex="0" role="textbox" aria-multiline="true" aria-label="Incident report content" aria-describedby="editor-help">
        <div id="editor-spacer"></div>
        <canvas id="editor-canvas"></canvas>
      </div>
      <footer class="statusbar">
        <span id="cursor-status">Ln 1, Col 1</span>
        <span id="caret-status">1 caret</span>
        <span id="revision-status">Revision —</span>
        <span id="editor-help">Alt+Click or Ctrl/Cmd+Click adds a caret</span>
      </footer>
    </section>
  </main>

  <aside id="history-panel" class="history-panel" aria-labelledby="history-title" hidden>
    <div class="panel-header">
      <div><span class="eyebrow">SAVED SNAPSHOTS</span><h2 id="history-title">Revision history</h2></div>
      <button id="history-close" type="button" aria-label="Close revision history">×</button>
    </div>
    <p>Preview a saved revision, then restore it as an unsaved draft.</p>
    <div id="revision-list" class="revision-list"></div>
    <div id="preview" class="preview" hidden>
      <div class="preview-header"><strong id="preview-title"></strong><button id="restore-button" class="primary" type="button">Restore as draft</button></div>
      <pre id="preview-content"></pre>
    </div>
  </aside>
  <script src="/editor.js"></script>
  <script src="/app.js"></script>
</body>
</html>
EOF
