:root { color-scheme: light; --ink:#202a35; --muted:#66727f; --line:#d9dee3; --paper:#fff; --accent:#0b6b5b; --accent-dark:#064b40; --blue:#dcecff; --danger:#a52a2a; }
* { box-sizing:border-box; }
body { margin:0; min-width:760px; background:#edf0f2; color:var(--ink); font:14px/1.4 Inter, ui-sans-serif, system-ui, sans-serif; }
button, input { font:inherit; }
button { border:1px solid #b9c1c8; border-radius:5px; background:#fff; color:var(--ink); padding:7px 11px; cursor:pointer; }
button:hover:not(:disabled) { border-color:#76818b; background:#f7f8f8; }
button:focus-visible, input:focus-visible, #editor:focus-visible { outline:2px solid #188c78; outline-offset:1px; }
button:disabled { opacity:.45; cursor:not-allowed; }
button.primary { border-color:var(--accent); background:var(--accent); color:#fff; font-weight:650; }
button.primary:hover:not(:disabled) { background:var(--accent-dark); }
.app-header { height:112px; padding:18px 28px; background:#17232d; color:#fff; display:flex; align-items:center; justify-content:space-between; border-bottom:4px solid #db9e31; }
.brand,.eyebrow { color:#efb653; font-size:11px; font-weight:800; letter-spacing:.12em; }
.brand span { color:#aab5be; margin-left:8px; font-weight:500; letter-spacing:.04em; }
h1 { font-family:Georgia,serif; font-size:27px; margin:5px 0 0; font-weight:500; }
#document-meta { color:#aeb8c0; margin:2px 0 0; font-size:12px; }
.header-actions { display:flex; align-items:center; gap:9px; }
.state-pill { padding:6px 10px; border:1px solid #5b6872; border-radius:99px; color:#cdd4da; font-size:12px; }
.state-pill.dirty { border-color:#e1a13b; color:#ffd68c; }
main { margin:16px 24px 24px; }
.toolbar { min-height:53px; background:#fff; border:1px solid var(--line); border-radius:7px 7px 0 0; display:flex; align-items:center; gap:17px; padding:8px 11px; }
.button-group { display:flex; gap:5px; padding-right:16px; border-right:1px solid var(--line); }
.search-group { display:flex; gap:7px; align-items:center; flex:1; }
.search-group label { color:var(--muted); font-size:12px; }
.search-group input { display:block; width:145px; height:28px; border:1px solid #b8c1c8; border-radius:4px; padding:3px 7px; color:var(--ink); }
#match-status { color:var(--muted); font-size:12px; margin-left:auto; }
.message { padding:9px 12px; background:#fff2f1; border:1px solid #e0aaa6; color:#87251f; font-weight:600; }
.message.info { background:#edf8f5; border-color:#acd5ca; color:#145f51; }
.editor-shell { border:1px solid var(--line); border-top:0; background:#fff; box-shadow:0 2px 10px #25313b12; }
#editor { position:relative; height:calc(100vh - 230px); min-height:390px; overflow:auto; background:var(--paper); cursor:text; }
#editor-spacer { position:absolute; left:0; top:0; pointer-events:none; }
#editor-canvas { position:absolute; left:0; top:0; display:block; }
.statusbar { height:30px; border-top:1px solid var(--line); background:#f6f7f7; color:#53606b; display:flex; align-items:center; gap:22px; padding:0 12px; font-size:12px; }
#editor-help { margin-left:auto; }
.history-panel { position:fixed; z-index:4; right:0; top:0; bottom:0; width:430px; background:#fff; box-shadow:-10px 0 35px #17232d33; padding:22px; overflow:auto; }
.panel-header,.preview-header { display:flex; justify-content:space-between; align-items:center; gap:12px; }
.panel-header h2 { font:25px Georgia,serif; margin:3px 0; }
#history-close { border:0; font-size:26px; padding:1px 8px; }
.revision-list { border-top:1px solid var(--line); margin-top:18px; }
.revision-item { display:flex; align-items:center; justify-content:space-between; padding:11px 2px; border-bottom:1px solid var(--line); }
.revision-item span { color:var(--muted); font-size:12px; display:block; }
.preview { margin-top:18px; border:1px solid var(--line); border-radius:5px; padding:10px; }
.preview pre { max-height:320px; overflow:auto; white-space:pre-wrap; background:#f5f6f7; padding:10px; font:11px/1.45 ui-monospace, monospace; }
@media (max-height:700px) { #editor { height:440px; } }
EOF

